    "asu-crna": {"prerequisites":[{"course":"Anatomy and physiology (two semesters or equivalent) - first semester","code":null,"category":"ap1","min_grade":"not_published","within_years":7,"by_when":"apply","one_of":null},{"course":"Anatomy and physiology (two semesters or equivalent) - second semester","code":null,"category":"ap2","min_grade":"not_published","within_years":7,"by_when":"apply","one_of":null},{"course":"General chemistry","code":null,"category":"chem","min_grade":"not_published","within_years":7,"by_when":"apply","one_of":null},{"course":"Statistics","code":null,"category":"stats","min_grade":"not_published","within_years":7,"by_when":"apply","one_of":null}],"rules":{"gpa_overall_min":"see_text","gpa_prereq_min":"not_published","gpa_science_min":3.2,"exam":"none","selection":"see_text","points":"not_applicable","retakes":"not_published","local_priority":"not_published","seats":"not_published"},"wording":{"prerequisites":"Required: \"two semesters or equivalent of anatomy and physiology,\" \"general chemistry,\" and \"statistics.\" \"Prerequisite courses must be completed within the seven years preceding application\"; \"coursework completed within five years is recommended.\"","gpa":"\"minimum cumulative GPA of 3.00 (scale is 4.00 = \"A\") in the last 60 hours of their first bachelor's degree program\" or a 3.00 minimum in an applicable master's program. Also \"a minimum 3.20 GPA (scale is 4.00 = \"A\") in all science courses completed.\"","exam":"\"An admission examination is not required.\"","selection":"\"Applications are reviewed on a space-available basis after the priority deadline.\" Applications completed before the priority deadline \"will receive priority consideration.\" \"An interview with program faculty is required.\"","points":null,"retakes":null,"local_priority":null,"seats":null},"source_urls":["https://degrees.asu.edu/masters-phd/major/ASU00/NUANPNADNP/advanced-nursing-practice-nurse-anesthesia-dnp","https://nursingandhealth.asu.edu/programs/dnp"],"last_verified":"2026-11-24","academic_year":"Fall 2027 admission","deadline":"Fall 2027 start: priority deadline Jan 15 (page shows 01/15 without a year); reviewed on a space-available basis after that.","notes":"Requires a bachelor's or master's in nursing and an unencumbered Arizona or compact multistate RN license (Arizona home state). \"Two years of experience as a full-time registered nurse is required prior to matriculation\"; \"one year of experience as a full-time critical care registered nurse is required prior to application\" (NICU and ED do not qualify). CCRN recommended; BLS, ACLS, PALS required before start. Shadowing a CRNA or anesthesiologist strongly recommended. Program pending COA accreditation; first-cohort offers conditional."},
    "u-arizona-fnp": {"prerequisites":[],"rules":{"gpa_overall_min":"see_text","gpa_prereq_min":"not_published","gpa_science_min":"not_published","exam":"not_published","selection":"competitive","points":"not_applicable","retakes":"not_published","local_priority":"not_published","seats":"not_published"},"wording":{"prerequisites":"No course prerequisites listed for this specialty. \"All applicants to DNP specialties must hold a current, unencumbered RN license.\" FNP: \"at least 1 year (a minimum of 1800 hours)\" \"in any RN role to apply full-time.\"","gpa":"\"minimum GPA of 3.00 (on a 4.00 scale) in nursing coursework for their most recent nursing degree.\"","exam":null,"selection":"\"Admission to the Doctor of Nursing Practice (DNP) program is competitive.\" NursingCAS review by the College of Nursing plus Graduate College approval; one specialty per cycle.","points":null,"retakes":null,"local_priority":null,"seats":null},"source_urls":["https://nursing.arizona.edu/academics/doctor-nursing-practice-dnp/specialties/family-nurse-practitioner-fnp","https://nursing.arizona.edu/academics/doctor-nursing-practice-dnp/admissions","https://nursing.arizona.edu/academics/doctor-nursing-practice-dnp","https://online.arizona.edu/programs/graduate/online-doctor-nursing-practice-nursing-family-nurse-practitioner-dnp"],"last_verified":"2026-11-24","academic_year":"Fall 2027 admission","deadline":"Fall 2027 start: applications open Aug 15; priority deadline Nov 1 (decision mid-December); final deadline Mar 1 (decision mid-April); 11:59 PM EST. The page gives no year; this cycle is for Fall 2027 starts, so the priority date is presumably Nov 1, 2026 (passed) and final Mar 1, 2027 - confirm with the school.","notes":"GPA is 3.00 in nursing coursework of the most recent nursing degree (not cumulative overall). No GRE or interview is mentioned. Accepted degrees: BSN, post-baccalaureate BSN, MEPN or MSN; conditional admission possible for students finishing a pre-licensure program, with RN license by end of first semester. Two professional references. Must complete the equivalent of 1 year full-time RN clinical experience (1,800 hours) before the clinical year. FNP: at least 1 year (1,800 hours) in any RN role to apply full-time; part-time applicants expected to work about 900 RN hours per year. Full-time and part-time options. The online.arizona.edu page used as the existing source gives no criteria and points to NursingCAS."},
