    "u-arizona-cnm": {"prerequisites":[],"rules":{"gpa_overall_min":"see_text","gpa_prereq_min":"not_published","gpa_science_min":"not_published","exam":"not_published","selection":"competitive","points":"not_applicable","retakes":"not_published","local_priority":"not_published","seats":"not_published"},"wording":{"prerequisites":"No course prerequisites listed for this specialty. \"All applicants to DNP specialties must hold a current, unencumbered RN license.\" Nurse-Midwifery: \"at least 1 year (a minimum of 1800 hours)\" in Labor & Delivery, Birth Center, Postpartum or OB/GYN Office.","gpa":"\"minimum GPA of 3.00 (on a 4.00 scale) in nursing coursework for their most recent nursing degree.\"","exam":null,"selection":"\"Admission to the Doctor of Nursing Practice (DNP) program is competitive.\" NursingCAS review by the College of Nursing plus Graduate College approval; one specialty per cycle.","points":null,"retakes":null,"local_priority":null,"seats":null},"source_urls":["https://nursing.arizona.edu/academics/dnp-program/specialties/nurse-midwifery","https://nursing.arizona.edu/academics/doctor-nursing-practice-dnp/admissions","https://nursing.arizona.edu/academics/doctor-nursing-practice-dnp"],"last_verified":"2026-11-24","academic_year":"Fall 2027 admission","deadline":"Fall 2027 start: applications open Aug 15; priority deadline Nov 1 (decision mid-December); final deadline Mar 1 (decision mid-April); 11:59 PM EST. The page gives no year; this cycle is for Fall 2027 starts, so the priority date is presumably Nov 1, 2026 (passed) and final Mar 1, 2027 - confirm with the school.","notes":"GPA is 3.00 in nursing coursework of the most recent nursing degree (not cumulative overall). No GRE or interview is mentioned. Accepted degrees: BSN, post-baccalaureate BSN, MEPN or MSN; conditional admission possible for students finishing a pre-licensure program, with RN license by end of first semester. Two professional references. Must complete the equivalent of 1 year full-time RN clinical experience (1,800 hours) before the clinical year. Nurse-Midwifery: at least 1 year (1,800 hours) in Labor & Delivery, Birth Center, Postpartum or OB/GYN Office. Hybrid format: online coursework with several on-campus intensives and a clinical practicum; \"Starts in Fall Semester Only.\" A Nurse-Midwifery Graduate Certificate is also listed (Summer 2027 start per the admissions page)."},
    "u-arizona-crna": {"prerequisites":[{"course":"Chemistry (1 semester)","code":null,"category":"chem","min_grade":"B","within_years":10,"by_when":"apply","one_of":null},{"course":"Biology (1 semester)","code":null,"category":"bio","min_grade":"B","within_years":10,"by_when":"apply","one_of":null},{"course":"Human Anatomy and Physiology I","code":null,"category":"ap1","min_grade":"B","within_years":10,"by_when":"apply","one_of":null},{"course":"Human Anatomy and Physiology II","code":null,"category":"ap2","min_grade":"B","within_years":10,"by_when":"apply","one_of":null},{"course":"Statistics (1 semester)","code":null,"category":"stats","min_grade":"B","within_years":10,"by_when":"apply","one_of":null}],"rules":{"gpa_overall_min":"see_text","gpa_prereq_min":"see_text","gpa_science_min":"not_published","exam":"not_published","selection":"competitive","points":"not_applicable","retakes":"not_published","local_priority":"not_published","seats":"not_published"},"wording":{"prerequisites":"\"Applicants must have completed all courses below with a B or better and an overall 3.0 or higher GPA within 10 years of the application deadline\": Chemistry: 1 semester; Biology: 1 semester; Human Anatomy and Physiology: 2 semesters; Statistics: 1 semester. \"AP and CLEP scores will not be accepted.\"","gpa":"\"minimum GPA of 3.00 (on a 4.00 scale) in nursing coursework for their most recent nursing degree\"; anesthesiology prerequisites \"with a B or better and an overall 3.0 or higher GPA within 10 years of the application deadline.\"","exam":null,"selection":"\"Admission to the Doctor of Nursing Practice (DNP) program is competitive.\" Three Likert references required; notification at the end of October.","points":null,"retakes":null,"local_priority":null,"seats":null},"source_urls":["https://nursing.arizona.edu/academics/doctor-nursing-practice-dnp/admissions","https://nursing.arizona.edu/academics/doctor-nursing-practice-dnp/specialties/nurse-anesthesiology"],"last_verified":"2026-11-24","academic_year":"Summer 2028 start","deadline":"Applications open June 1; deadline August 1 (11:59 PM EST); notification end of October; starts Summer semester only. The page gives no year (the admissions page lists the next start as Summer 2028): confirm the next deadline with the school.","notes":"\"a minimum of 1 year (a minimum of 1800 hours) of critical care ICU work\" \"within the last 3 years of the application deadline.\" Counts: coronary, cardiac, burn, medical, surgical, trauma, neuro ICU; does not count: neonatal ICU, emergency room, pediatric ICU. CCRN, ACLS, BLS and PALS (AHA) before the application deadline; CCRN score must be provided. Three Likert references. Full-time only. $3,000 deposit on acceptance. Current unencumbered RN license required. No GRE mentioned."},
    "nau-fnp": {"prerequisites":[{"course":"Undergraduate nursing research (didactic)","code":null,"category":"other","min_grade":"B","within_years":"not_published","by_when":"not_published","one_of":null},{"course":"Undergraduate public health nursing (didactic and clinical)","code":null,"category":"other","min_grade":"B","within_years":"not_published","by_when":"not_published","one_of":null},{"course":"Introductory statistics (undergraduate, or graduate statistics)","code":null,"category":"stats","min_grade":"see_text","within_years":"not_published","by_when":"see_text","one_of":null}],"rules":{"gpa_overall_min":"see_text","gpa_prereq_min":"not_published","gpa_science_min":"not_published","exam":"not_published","selection":"see_text","points":"not_applicable","retakes":"not_published","local_priority":"not_published","seats":"not_published"},"wording":{"prerequisites":"Undergraduate nursing research (didactic) and public health nursing (didactic and clinical), grade \"B\" or better. Undergraduate intro statistics with a \"C\" or better or Pass, or graduate statistics with a \"B\" or better, which \"must be completed prior to enrollment in NUR 530.\"","gpa":"\"A minimum GPA of 3.0 in all nursing coursework\" (how-to-apply: \"minimum 3.0 GPA on a 4.0 scale in all nursing coursework of the BSN or AAS in nursing\"). Applicants below 3.0 are advised to take two graduate nursing courses and earn B or better.","exam":null,"selection":"\"Admission to many graduate programs is on a competitive basis.\" \"A structured interview with College of Nursing faculty may be required.\" Essay responses and resume/CV required.","points":null,"retakes":null,"local_priority":null,"seats":null},"source_urls":["https://in.nau.edu/college-nursing/graduate-degrees-programs/ms-nursing-advanced-practice/","https://in.nau.edu/college-nursing/how-to-apply/graduate-nursing-programs/"],"last_verified":"2026-11-24","academic_year":"2026-27","deadline":"not_published","notes":"Requires a BSN, or an ADN plus a bachelor's in another field, and a current RN license in good standing in Arizona (or eligibility / multistate). NAU recommends 3-5 years of nursing practice before applying (not a minimum). IVP fingerprint clearance card, essays and resume/CV required. GRE not mentioned. NAU's DNP is 'not currently accepting applications' (does not affect the MS)."},
