    "gcu-fnp": {"prerequisites":[],"rules":{"gpa_overall_min":3,"gpa_prereq_min":"not_published","gpa_science_min":"not_published","exam":"see_text","selection":"see_text","points":"not_applicable","retakes":"not_published","local_priority":"not_published","seats":"not_published"},"wording":{"prerequisites":"No admission course prerequisites listed. Advanced pharmacology, pathophysiology and health assessment are non-transferable (appeal possible if taken within five years).","gpa":"\"Candidates' transcripts must reflect a cumulative grade point average of 3.0 or above.\" APRN applicants \"are required to be fully accepted. APRN students cannot be accepted with specifications.\"","exam":"General master's page: applicants below the GPA requirement \"may be eligible\" with test scores (GMAT 500; GRE 300 verbal/quantitative after Aug 2011). The handbook's APRN addendum says APRN students cannot be accepted with specifications, so the test-score route may not apply.","selection":"\"Final acceptance into the program will be determined by the College of Nursing and Health Care Professions Admissions Committee.\" Denied applicants may reapply after 180 days.","points":null,"retakes":null,"local_priority":null,"seats":null},"source_urls":["https://www.gcu.edu/sites/default/files/media/documents/academics/handbook/2026-27/university-policy-handbook-fall-2026-v2.pdf","https://www.gcu.edu/degree-programs/msn-family-nurse-practitioner","https://www.gcu.edu/admissions/graduate-doctoral"],"last_verified":"2026-11-24","academic_year":"2026-27 (Fall 2026 University Policy Handbook)","deadline":"not_published","notes":"Requires a current unencumbered, unrestricted RN license; program page says a BSN from a CCNE/NLNAC/ACEN-accredited program (bachelor's in a related field: bridge to MSN first). CV showing at least one year full-time RN experience within the last 12 months; must be currently employed full-time in direct patient care and remain employed until start (indirect-care nurses ineligible). Offer valid 12 months. Offered to residents of listed states including Arizona."},
